  fovPunchHit: 1.6, fovPunchKill: 4.5, kickHit: 0.16, kickKill: 0.5,
  camKickDecay: 11, fovDecay: 7, trailLife: 0.14,
  // weighty offense (RMB heavy): wide cleave, big radial knockback, group stagger
