  if (fieldSimOn() && gameRunning && !encounter && !musterOpen && fieldStrike && !fieldBattle && (e.code === 'Enter' || e.code === 'NumpadEnter')) { e.preventDefault(); launchStrike(fieldStrike.band, 'all'); return; }
