      if (!band.inBattle.server && d < 4.2 && band.parleyCd <= 0 && !fieldSimOn() && -(player.vel.x * to.x + player.vel.z * to.z) > 0.3) { openEncounter(band); return; } // on foot, no prompt — attack to fight
      continue;
