function holdNear(x, z, r) { let best = null, bd = r * r; for (const h of nations.concat(settlements)) { const dx = h.x - x, dz = h.z - z, dd = dx * dx + dz * dz; if (dd < bd) { bd = dd; best = h; } } return best; }
