      ti = Terra.make((R() * 0xffffffff) >>> 0);
      ox = (R() * 2 - 1) * 6000; oz = (R() * 2 - 1) * 6000; base = ti.elevationAt(ox, oz);
      if (base < SEA + 0.03) continue;                        // not underwater / on the coast
