  for (let i = 0; i < nk; i++) t.knolls.push({ x: (R() * 2 - 1) * t.half * 0.55, z: (R() * 2 - 1) * 40, h: 3 + R() * 6, r: 7 + R() * 8 });
  t.peakRef = Math.max(t.peakL, t.peakR);
