BV.battle = (cfg) => { if (!BATTLE.on) battleBoot(cfg || {}); else { BATTLE.cfg = { ...BATTLE.cfg, ...(cfg || {}) }; battleSetup(); } return { perSide: BATTLE.cfg.perSide, seed: BATTLE.cfg.seed }; };
