  renderer.toneMappingExposure = T.exp;
  if (PBR_ON) setEnvMap(makeEnvMap(skyC[0].getHex(), skyC[1].getHex(), skyC[2].getHex(), sun.position, T.sunCol));   // the plates reflect the hour
