    for (let i = 0; i < n; i++) { const a = Math.random() * TAU, e = Math.asin(Math.random() * 0.95 + 0.05), r = 222; pos[i * 3] = Math.cos(a) * Math.cos(e) * r; pos[i * 3 + 1] = Math.sin(e) * r; pos[i * 3 + 2] = Math.sin(a) * Math.cos(e) * r; }
