  if (!g) { const L = AF.bodies; for (let i = 0; i < L.length; i++) { const b = L[i]; if (b.dead) continue; for (let j = i + 1; j < L.length; j++) { const o = L[j]; if (!o.dead) afShove(b, o); } } return; }
