    let alive = 0, hp = 0, kills = 0, names = [];
    for (const b of AF.bodies) if (b.team === t) { kills += b.kills; if (!b.dead) { alive++; hp += b.hp; names.push(b.name); } }
    st.push({ team: t, alive, hp: Math.round(hp), kills, names });
